/**
 * Workspace template directory discovery.
 * Resolves packaged documentation templates for source and installed runtimes.
 */
import path from "node:path";
import { fileURLToPath } from "node:url";
import { resolveOpenClawPackageRoot } from "../infra/openclaw-root.js";
import { pathExists } from "../utils.js";
import { DEFAULT_AGENTS_FILENAME, DEFAULT_SOUL_FILENAME } from "./workspace-bootstrap-policy.js";

// Previously shipped generated bytes, so template edits do not make an
// untouched seed look customized and end a pending bootstrap.
export const RETIRED_GENERATED_TEMPLATE_SHA256: Readonly<Record<string, readonly string[]>> = {
  [DEFAULT_AGENTS_FILENAME]: [
    "1e17784e422c0e47e44c5214d0b37092f7b378bb2d3746976032be3075203c88",
    "490fc2b32865dd310a3af1225a409ac5c942d89ba456167feb0fd95e2807aaff",
    "ac7c735bbf21f072f8abd775d65fab56913f6bcdea2235ba1d88d48f2bf31d6a",
  ],
  [DEFAULT_SOUL_FILENAME]: ["4f9042f259b076e429d0f01ce39340030f47ea5b7f5befe306296c36baf1f60f"],
};

const FALLBACK_DOCS_TEMPLATE_DIR = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../../docs/reference/templates",
);

/** Resolves existing packaged workspace-template directories without retired runtime paths. */
export async function resolveWorkspaceTemplateSearchDirs(opts?: {
  cwd?: string;
  argv1?: string;
  moduleUrl?: string;
}): Promise<string[]> {
  const moduleUrl = opts?.moduleUrl ?? import.meta.url;
  const argv1 = opts?.argv1 ?? process.argv[1];
  const cwd = opts?.cwd ?? process.cwd();

  const packageRoot = await resolveOpenClawPackageRoot({ moduleUrl, argv1, cwd });
  const relativeDir = path.join("docs", "reference", "templates");
  const candidates = [
    packageRoot ? path.join(packageRoot, relativeDir) : undefined,
    path.resolve(cwd, relativeDir),
    FALLBACK_DOCS_TEMPLATE_DIR,
  ];
  const dirs: string[] = [];
  for (const candidate of candidates) {
    if (candidate && !dirs.includes(candidate) && (await pathExists(candidate))) {
      dirs.push(candidate);
    }
  }
  return dirs;
}
